import{_ as t,o,c as a,a0 as r}from"./chunks/framework.BGyYNsHo.js";const c=JSON.parse('{"title":"Getting Started with Local SWMM","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/01-getting-started.md","filePath":"tutorials/01-getting-started.md"}'),i={name:"tutorials/01-getting-started.md"};function n(s,e,l,h,d,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="getting-started-with-local-swmm" tabindex="-1">Getting Started with Local SWMM <a class="header-anchor" href="#getting-started-with-local-swmm" aria-label="Permalink to &quot;Getting Started with Local SWMM&quot;">​</a></h1><p>In this tutorial you will learn what LocalSWMM is, what you need to run it, and how to open the app and complete your first simulation with a built-in sample model.</p><h2 id="what-you-ll-be-doing" tabindex="-1">What you&#39;ll be doing <a class="header-anchor" href="#what-you-ll-be-doing" aria-label="Permalink to &quot;What you&#39;ll be doing&quot;">​</a></h2><p>By the end of this lesson you will have:</p><ul><li>opened the Local SWMM web application,</li><li>explored its five main interface areas,</li><li>loaded a sample drainage network, and</li><li>run a hydraulic simulation and inspected its results.</li></ul><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A modern web browser with WebGL support <strong>enabled</strong>. <a href="https://get.webgl.org/" target="_blank" rel="noreferrer">Check here if you can properly use it on your browser</a> and learn how to activate it by following the website instructions.</li><li>Python 3 installed on your computer /if/ you want to run the app from your own machine. (Node is only needed for <code>npm install</code> and the tooling scripts.)</li></ul><h2 id="what-localswmm-is" tabindex="-1">What LocalSWMM is <a class="header-anchor" href="#what-localswmm-is" aria-label="Permalink to &quot;What LocalSWMM is&quot;">​</a></h2><p>LocalSWMM is an interactive, browser-based web application for 1D hydraulic modeling and simulation of urban stormwater and wastewater networks. Both the network editor and the computational engine run entirely client-side.</p><p>Key properties:</p><ul><li><strong>No backend required:</strong> A minimal local Python server (<code>server.py</code>) serves static assets and a health endpoint. No database, external solver, or backend computation is required.</li><li><strong>Dependency-free UI:</strong> Built with standard JavaScript (classic scripts + IIFEs) without heavy UI frameworks, using Mapbox GL JS for 2D/3D map and terrain visualization.</li><li><strong>In-browser hydraulics:</strong> The <a href="https://github.com/HydroCouple/openswmm.engine" target="_blank" rel="noreferrer">HydroCouple OpenSWMM engine</a> is cross-compiled to WebAssembly via Emscripten, enabling full hydrodynamic simulations right inside your browser.</li></ul><p>You can try the live app at <strong><a href="https://swmm6.is-local.org" target="_blank" rel="noreferrer">https://swmm6.is-local.org</a></strong>. A demo video is available at <a href="https://github.com/user-attachments/assets/6ea0af51-125d-4b7d-a6ba-e0452cfae368" target="_blank" rel="noreferrer">https://github.com/user-attachments/assets/6ea0af51-125d-4b7d-a6ba-e0452cfae368</a> (or <code>assets/demo.mp4</code> in the repository).</p><h2 id="step-1-open-the-app" tabindex="-1">Step 1: Open the app <a class="header-anchor" href="#step-1-open-the-app" aria-label="Permalink to &quot;Step 1:  Open the app&quot;">​</a></h2><p>The fastest way to start is the production site: <strong><a href="https://swmm6.is-local.org" target="_blank" rel="noreferrer">https://swmm6.is-local.org</a></strong>.</p><p>If you prefer to run the app on your own computer instead, follow the guide <a href="./../how-to/01-run-locally.html">How to Run the App Locally</a> first, then come back and follow the next steps.</p><h2 id="step-2-get-to-know-the-interface" tabindex="-1">Step 2: Get to know the interface <a class="header-anchor" href="#step-2-get-to-know-the-interface" aria-label="Permalink to &quot;Step 2:  Get to know the interface&quot;">​</a></h2><p>The user interface contains five main areas:</p><ul><li><strong>Top Toolbar</strong>: Perform file operations, change simulation options, and run simulations.</li><li><strong>Left Tool Palette</strong>: Select map objects or draw network elements.</li><li><strong>Map View</strong>: View and edit your drainage network over interactive 2D or 3D maps.</li><li><strong>Right Side Panel</strong>: Inspect element properties or view simulation result tables.</li><li><strong>Bottom Status Bar</strong>: View current tool selection, element counts, and cursor coordinates.</li></ul><h2 id="step-3-load-a-sample-model" tabindex="-1">Step 3: Load a sample model <a class="header-anchor" href="#step-3-load-a-sample-model" aria-label="Permalink to &quot;Step 3: Load a sample model&quot;">​</a></h2><p>The project ships one pre configured sample model:</p><ol><li>On the <strong>Top Toolbar</strong>, open the <strong>Open Model ▾</strong> dropdown.</li><li>Choose <strong>Load Sample Models</strong>.</li><li>Load <strong>Bellinge Web</strong>.</li></ol><p>You should now see the reference network on the map. <strong>Bellinge Web</strong> is the reference network used throughout the test suite.</p><h2 id="step-4-—-run-the-simulation" tabindex="-1">Step 4 — Run the simulation <a class="header-anchor" href="#step-4-—-run-the-simulation" aria-label="Permalink to &quot;Step 4 — Run the simulation&quot;">​</a></h2><ol><li>Press <strong>Run</strong> on the <strong>Top Toolbar</strong>.</li><li>Monitor progress in the <strong>Run Status</strong> window. It shows: <ul><li><strong>Progress Tracking</strong>: real time calculation progress percentage and simulated time (<code>Days</code> and <code>Hrs:Min</code>).</li><li><strong>Stop Simulation</strong>: click <strong>Stop</strong> to stop the simulation immediately.</li><li><strong>Minimize Window</strong>: click <strong>Minimize</strong> to shrink the status window into a floating badge. Click <strong>Expand</strong> on the floating badge to restore the window.</li></ul></li></ol><h2 id="step-5-—-look-at-the-results" tabindex="-1">Step 5 — Look at the results <a class="header-anchor" href="#step-5-—-look-at-the-results" aria-label="Permalink to &quot;Step 5 — Look at the results&quot;">​</a></h2><ul><li><strong>Time Slider Panel</strong>: use the bottom animation bar to play, pause, change speed, or drag to a specific time step.</li><li><strong>Properties Tab</strong>: click any node or link to view its geometric properties and calculated flow values.</li><li><strong>Results Tab</strong>: select result categories to view summary tables (Node Depths, Node Inflows, Link Flows, and Subcatchment Runoff).</li><li><strong>Water Elevation Profile</strong>: select connected nodes and click <strong>Profile</strong> to view an interactive hydraulic profile plot.</li></ul><h2 id="what-you-should-see-at-the-end" tabindex="-1">What you should see at the end <a class="header-anchor" href="#what-you-should-see-at-the-end" aria-label="Permalink to &quot;What you should see at the end&quot;">​</a></h2><ul><li>A finished run: the <strong>Run Status</strong> window reaches 100 %, and the <strong>Results</strong> and <strong>Report</strong> tabs in the right panel are populated.</li><li>An animated timeline: the <strong>Time Slider</strong> plays back the simulated period, and result colors update on the map.</li><li>You are now ready to build your own network — continue with <a href="./02-your-first-network.html">Build Your First Drainage Network</a>.</li></ul>',28)])])}const g=t(i,[["render",n]]);export{c as __pageData,g as default};
